class Evaluator:
    def __init__(self, expression):
        self.expression = expression.replace(" ", "")
        self.index = 0

    def error(self):
        raise ValueError("Invalid expression")

    def get_number(self):
        number = ''
        while (self.index < len(self.expression) and 
               (self.expression[self.index].isdigit() or self.expression[self.index] == '.')):
            number += self.expression[self.index]
            self.index += 1
        if number:
            return float(number)
        return None

    def peek(self):
        if self.index < len(self.expression):
            return self.expression[self.index]
        return None

    def evaluate_term(self):
        result = self.get_number()
        if result is None:
            self.error()

        while self.index < len(self.expression):
            operator = self.peek()
            if operator in ('*', '/'):
                self.index += 1  # consume operator
                next_number = self.get_number()
                if operator == '*':
                    result *= next_number
                elif operator == '/':
                    result /= next_number
            else:
                break
        return result

    def evaluate_expression(self):
        result = self.evaluate_term()
        while self.index < len(self.expression):
            operator = self.peek()
            if operator in ('+', '-'):
                self.index += 1  # consume operator
                next_term = self.evaluate_term()
                if operator == '+':
                    result += next_term
                elif operator == '-':
                    result -= next_term
            else:
                break
        return result

