def evaluate(expr: str) -> float:
    """
    Evaluate the arithmetic expression using the Shunting Yard algorithm 
    to convert the expression to Reverse Polish Notation (RPN) and then 
    evaluate the RPN expression.
    """

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def shunting_yard(expression):
        output = []
        operators = []
        index = 0
        while index < len(expression):
            ch = expression[index]
            if ch.isdigit() or ch == '.':
                num = ''
                while index < len(expression) and (expression[index].isdigit() or expression[index] == '.'):
                    num += expression[index]
                    index += 1
                output.append(float(num))
                continue
            elif ch in '+-*/()':
                if ch == '(':
                    operators.append(ch)
                elif ch == ')':
                    while operators and operators[-1] != '(':
                        output.append(operators.pop())
                    operators.pop()  # Pop the '('
                else:
                    while (operators and precedence(operators[-1]) >= precedence(ch)):
                        output.append(operators.pop())
                    operators.append(ch)
            index += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

    rpn = shunting_yard(expr)
    return evaluate_rpn(rpn)

