        token, token_type = tokens[i]
        if token_type == 'NUMBER':
            operands.append(token)
        elif token_type == 'PLUS' or token_type == 'MINUS':
            while (operators and precedence(operators[-1]) >= precedence(token_type)):
                apply_operation(operators, operands)
            operators.append(token_type)
        elif token_type == 'MULTIPLY' or token_type == 'DIVIDE':
